import sys

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def main():
    n = int(sys.stdin.read().strip())
    colors = [0] * (n + 1)
    color_count = 0

    for i in range(2, n + 1):
        if colors[i] == 0:
            color_count += 1
            colors[i] = color_count
            for j in range(i * 2, n + 1, i):
                if is_prime(i):
                    colors[j] = color_count

    print(color_count)
    print(' '.join(str(colors[i]) for i in range(2, n + 1)))

main()
